import sys
def main():
    s = sys.stdin.buffer.read().decode().rstrip("\r\n")
    def pal(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1; j -= 1
        return True
    i, j = 0, len(s) - 1
    ok = True
    while i < j:
        if s[i] != s[j]:
            ok = pal(i + 1, j) or pal(i, j - 1)
            break
        i += 1; j -= 1
    print("Yes" if ok else "No")
main()
